<?php
function sessionRows($q=[],$faceOnly=false){$sql="SELECT sess.*,sub.name subject_name,sub.code subject_code,CONCAT(cd.year_level,' ',cd.division) division_name,u.full_name faculty_name,(SELECT COUNT(*) FROM attendance_records ar WHERE ar.session_id=sess.id) total_students,(SELECT COUNT(*) FROM attendance_records ar WHERE ar.session_id=sess.id) total_enrolled,(SELECT COUNT(*) FROM attendance_records ar WHERE ar.session_id=sess.id AND ar.status='PRESENT') present_count,(SELECT COUNT(*) FROM attendance_records ar WHERE ar.session_id=sess.id AND ar.status='ABSENT') absent_count,(SELECT COUNT(*) FROM attendance_records ar WHERE ar.session_id=sess.id AND ar.status='LATE') late_count FROM attendance_sessions sess JOIN subjects sub ON sub.id=sess.subject_id JOIN class_divisions cd ON cd.id=sess.division_id JOIN users u ON u.id=sess.faculty_user_id WHERE 1=1";$p=[];scopeSql($sql,$p,'cd.department_id');if($faceOnly)$sql.=" AND sess.source='FACE_RECOGNITION'";filterSql($sql,$p,['division_id'=>'sess.division_id','subject_id'=>'sess.subject_id','date'=>'sess.session_date','faculty_id'=>'sess.faculty_user_id'],$q);return rows($sql.' ORDER BY sess.session_date DESC,sess.created_at DESC LIMIT 50',$p);}
function saveAttendance($b,$source='MANUAL'){
 $u=role();divisionAccess($b['division_id']??'');need($b,['subject_id','division_id','session_date','lecture_slot','records']);if(!is_array($b['records'])||!count($b['records']))fail('Provide attendance records.');validateDate($b['session_date']);$sub=one('SELECT * FROM subjects WHERE id=? AND division_id=?',[$b['subject_id'],$b['division_id']]);if(!$sub)fail('Subject does not belong to the selected division.');if(!in_array($source,['MANUAL','FACE_RECOGNITION','OFFLINE_SYNC']))fail('Invalid attendance source.');
 $existing=one('SELECT * FROM attendance_sessions WHERE subject_id=? AND division_id=? AND session_date=? AND lecture_slot=? FOR UPDATE',[$b['subject_id'],$b['division_id'],$b['session_date'],$b['lecture_slot']]);if($existing)editable($existing['created_at']);$id=$existing['id']??uid('sess-');
 if(!$existing)insertRow('attendance_sessions',['id'=>$id,'subject_id'=>$b['subject_id'],'division_id'=>$b['division_id'],'faculty_user_id'=>$u['id'],'session_date'=>$b['session_date'],'lecture_slot'=>$b['lecture_slot'],'room_no'=>$b['room_no']??'Classroom 204','status'=>'SUBMITTED','source'=>$source]);
 if($source==='FACE_RECOGNITION')updateRow('attendance_sessions',$id,['source'=>$source,'total_faces'=>(int)($b['total_faces']??0),'recognized_faces'=>(int)($b['recognized_faces']??0),'unknown_faces'=>(int)($b['unknown_faces']??0),'uploaded_image_reference'=>$b['image_reference']??null]);
 $seen=[];foreach($b['records'] as $r){need($r,['student_id']);$sid=$r['student_id'];if(isset($seen[$sid]))fail('Duplicate student attendance record.');$seen[$sid]=true;$st=one('SELECT id FROM students WHERE id=? AND division_id=? AND is_active=1',[$sid,$b['division_id']]);if(!$st)fail('Attendance includes an inactive student or a student from another division.');$status=strtoupper($r['status']??'PRESENT');if(!in_array($status,['PRESENT','ABSENT','LATE','LEAVE','EXCUSED']))fail('Invalid attendance status.');$confidence=$r['recognition_confidence']??null;if($confidence!==null&&(!is_numeric($confidence)||$confidence<0||$confidence>1))fail('Invalid recognition confidence.');$old=one('SELECT * FROM attendance_records WHERE session_id=? AND student_id=?',[$id,$sid]);$data=['status'=>$status,'marked_by_user_id'=>$u['id'],'marked_at'=>gmdate('Y-m-d H:i:s'),'attendance_method'=>$source==='FACE_RECOGNITION'?'FACE_RECOGNITION':'MANUAL','recognition_confidence'=>$confidence];if($old){if($old['status']!==$status){insertRow('attendance_audit_logs',['id'=>uid(),'record_id'=>$old['id'],'session_id'=>$id,'student_id'=>$sid,'previous_status'=>$old['status'],'new_status'=>$status,'changed_by_user_id'=>$u['id'],'reason'=>'Attendance session resubmitted']);$data['original_status']=$old['original_status']??$old['status'];$data['original_method']=$old['original_method']??$old['attendance_method'];$data['modified_by']=$u['full_name'];$data['modified_at']=gmdate('Y-m-d H:i:s');}updateRow('attendance_records',$old['id'],$data);}else insertRow('attendance_records',['id'=>uid('rec-'),'session_id'=>$id,'student_id'=>$sid,...$data]);}
 if($source==='FACE_RECOGNITION')logBio('ATTENDANCE_SCAN',null,'Face attendance confirmed for session '.$id);return ['success'=>true,'message'=>'Attendance successfully saved.','sessionId'=>$id,'totalMarked'=>count($b['records'])];
}
if($path==='/attendance/sessions'&&$method==='GET'){role();send(['sessions'=>sessionRows($q)]);}
if(preg_match('#^/attendance/session/([^/]+)$#',$path,$m)&&$method==='GET'){role();$sessions=sessionRows();$sess=one("SELECT sess.*,sub.name subject_name,sub.code subject_code,CONCAT(cd.year_level,' ',cd.division) division_name,u.full_name faculty_name FROM attendance_sessions sess JOIN subjects sub ON sub.id=sess.subject_id JOIN class_divisions cd ON cd.id=sess.division_id JOIN users u ON u.id=sess.faculty_user_id WHERE sess.id=?",[$m[1]])??fail('Attendance session not found.',404);$recs=rows('SELECT ar.*,s.roll_no,s.prn,s.full_name student_name,s.photo_url FROM attendance_records ar JOIN students s ON s.id=ar.student_id WHERE ar.session_id=? ORDER BY s.roll_no',[$m[1]]);$allowed=true;$reason=null;try{editable($sess['created_at']);}catch(ApiError $e){$allowed=false;$reason=$e->getMessage();}send(['session'=>$sess,'records'=>$recs,'isEditable'=>$allowed,'editRestrictionReason'=>$reason]);}
if($path==='/attendance/mark'&&$method==='POST'){role();send(transaction(fn()=>saveAttendance($body,$body['source']??'MANUAL')),201);}
if($path==='/attendance/sync'&&$method==='POST'){role();if(empty($body['sessions'])||!is_array($body['sessions']))fail('No offline sessions to sync.');$count=transaction(function()use($body){foreach($body['sessions'] as $s)saveAttendance($s,'OFFLINE_SYNC');return count($body['sessions']);});send(['success'=>true,'message'=>'Offline attendance synchronized.','syncedCount'=>$count]);}
if(preg_match('#^/attendance/(?:record|student-record)/([^/]+)$#',$path,$m)){
 $u=role();$record=one('SELECT ar.*,sess.session_date,sess.created_at session_created_at FROM attendance_records ar JOIN attendance_sessions sess ON sess.id=ar.session_id WHERE ar.id=?',[$m[1]])??fail('Attendance record not found.',404);
 if($method==='PUT'){need($body,['new_status','reason']);$status=strtoupper(trim($body['new_status']));if(!in_array($status,['PRESENT','ABSENT','LATE','LEAVE','EXCUSED']))fail('Invalid attendance status.');if(trim($body['reason'])==='')fail('Provide a reason for this edit.');editable($record['session_created_at']);transaction(function()use($record,$u,$body,$status){updateRow('attendance_records',$record['id'],['status'=>$status,'attendance_method'=>'Manual Edit','original_status'=>$record['original_status']??$record['status'],'original_method'=>$record['original_method']??$record['attendance_method'],'modified_by'=>$u['full_name'],'modified_at'=>gmdate('Y-m-d H:i:s'),'marked_by_user_id'=>$u['id'],'marked_at'=>gmdate('Y-m-d H:i:s')]);insertRow('attendance_audit_logs',['id'=>uid(),'record_id'=>$record['id'],'session_id'=>$record['session_id'],'student_id'=>$record['student_id'],'previous_status'=>$record['status'],'new_status'=>$status,'changed_by_user_id'=>$u['id'],'reason'=>trim($body['reason'])]);});$updated=one('SELECT ar.*,sess.session_date,sess.lecture_slot,sub.name subject_name FROM attendance_records ar JOIN attendance_sessions sess ON sess.id=ar.session_id JOIN subjects sub ON sub.id=sess.subject_id WHERE ar.id=?',[$record['id']]);send(['success'=>true,'message'=>'Attendance record updated.','previousStatus'=>$record['status'],'newStatus'=>$status,'record'=>$updated]);}
 if($method==='DELETE'){role('ADMIN');transaction(function()use($record,$u){insertRow('attendance_audit_logs',['id'=>uid(),'record_id'=>$record['id'],'session_id'=>$record['session_id'],'student_id'=>$record['student_id'],'previous_status'=>$record['status'],'new_status'=>'DELETED','changed_by_user_id'=>$u['id'],'reason'=>'Record deleted by Administrator']);query('DELETE FROM attendance_records WHERE id=?',[$record['id']]);});send(['success'=>true,'message'=>'Attendance record deleted.']);}
}
if($path==='/attendance/audit-logs'&&$method==='GET'){role('ADMIN');$sql='SELECT al.*,u.full_name changed_by_name,u.role changed_by_role,s.full_name student_name,s.roll_no student_roll,sub.name subject_name FROM attendance_audit_logs al JOIN users u ON u.id=al.changed_by_user_id JOIN students s ON s.id=al.student_id JOIN attendance_sessions sess ON sess.id=al.session_id JOIN subjects sub ON sub.id=sess.subject_id WHERE 1=1';$p=[];filterSql($sql,$p,['session_id'=>'al.session_id','student_id'=>'al.student_id'],$q);send(['logs'=>rows($sql.' ORDER BY al.changed_at DESC LIMIT 100',$p)]);}
